     1→import { Block, Text } from "@prototyp/skeletor";
     2→import { FlashList, type FlashListRef } from "@shopify/flash-list";
     3→import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
     4→import { useAtom } from "jotai";
     5→import {
     6→  addDateDividers,
     7→  getEventId,
     8→  getItemUniqueKey,
     9→} from "modules/matrix-client/utils";
    10→import { useRoomTimeline } from "modules/timeline/hooks";
    11→import { TimelineAtoms } from "modules/timeline/jotai";
    12→import {
    13→  filterSameStateKey,
    14→  handleIsPreviousSameSender,
    15→} from "modules/timeline/utils";
    16→import {
    17→  type FC,
    18→  useCallback,
    19→  useEffect,
    20→  useMemo,
    21→  useRef,
    22→  useState,
    23→} from "react";
    24→import {
    25→  Image,
    26→  KeyboardAvoidingView,
    27→  type NativeScrollEvent,
    28→  type NativeSyntheticEvent,
    29→  StyleSheet,
    30→} from "react-native";
    31→import {
    32→  Button,
    33→  ImageViewerModal,
    34→  Loading,
    35→  MemberDetailsBottomSheet,
    36→  VideoViewerModal,
    37→} from "shared/components";
    38→import { useMemberDetails } from "shared/hooks";
    39→import { DateDivider } from "../date-divider";
    40→import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
    41→import { RoomInput } from "../room-input";
    42→import { SingleMessageType } from "../single-message-type";
    43→
    44→interface Props {
    45→  room: RoomInterface;
    46→  roomId: string;
    47→}
    48→
    49→export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
    50→  const flatListRef = useRef<FlashListRef<TimelineListItem>>(null);
    51→  const isAtBottomRef = useRef(true);
    52→  const lastEventKeyRef = useRef<string | undefined>(undefined);
    53→  const [showScrollDown, setShowScrollDown] = useState(false);
    54→  const {
    55→    events,
    56→    loadingMessage,
    57→    refreshing,
    58→    updateTrigger,
    59→    isDirect,
    60→    loadMoreMessages,
    61→    markAsRead,
    62→  } = useRoomTimeline({
    63→    room,
    64→    roomId,
    65→  });
    66→  const [scrollToEventId, setScrollToEventId] = useAtom(
    67→    TimelineAtoms.scrollToEventId,
    68→  );
    69→  const {
    70→    selectedMember,
    71→    isBottomSheetOpen,
    72→    openMemberDetails,
    73→    closeMemberDetails,
    74→  } = useMemberDetails();
    75→
    76→  const sortedEvents = useMemo(() => {
    77→    const sorted = [...events].sort(
    78→      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    79→    );
    80→
    81→    return filterSameStateKey(sorted);
    82→  }, [events]);
    83→
    84→  const eventsWithDividers = useMemo(() => {
    85→    return addDateDividers(sortedEvents);
    86→  }, [sortedEvents]);
    87→
    88→  const handleScrollToEvent = useCallback(
    89→    (eventId: string) => {
    90→      const index = eventsWithDividers.findIndex(
    91→        (item) => item.type === "event" && getEventId(item.data) === eventId,
    92→      );
    93→      if (index === -1) return;
    94→
    95→      flatListRef.current?.scrollToIndex({
    96→        index,
    97→        animated: true,
    98→        viewPosition: 0.5,
    99→      });
   100→    },
   101→    [eventsWithDividers],
   102→  );
   103→
   104→  useEffect(() => {
   105→    if (!scrollToEventId) return;
   106→    handleScrollToEvent(scrollToEventId);
   107→    setScrollToEventId(null);
   108→  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
   109→
   110→  const handleLoadMore = async () => {
   111→    setShowScrollDown(false);
   112→    await loadMoreMessages();
   113→  };
   114→
   115→  const handleScrollDown = () => {
   116→    flatListRef.current?.scrollToEnd({ animated: true });
   117→    setShowScrollDown(false);
   118→  };
   119→
   120→  const handleOnScroll = ({
   121→    nativeEvent,
   122→  }: NativeSyntheticEvent<NativeScrollEvent>) => {
   123→    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
   124→    const paddingToBottom = 100;
   125→    const atBottom =
   126→      layoutMeasurement.height + contentOffset.y >=
   127→      contentSize.height - paddingToBottom;
   128→    isAtBottomRef.current = atBottom;
   129→    if (!atBottom) return;
   130→    setShowScrollDown(false);
   131→    markAsRead();
   132→  };
   133→
   134→  const handleContentSizeChange = () => {
   135→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   136→    const lastEventKey = lastEvent
   137→      ? (getItemUniqueKey(lastEvent) ?? undefined)
   138→      : undefined;
   139→    const isNewEvent = lastEventKey !== lastEventKeyRef.current;
   140→    lastEventKeyRef.current = lastEventKey;
   141→    if (!isNewEvent || !lastEvent?.isOwn) return;
   142→    flatListRef.current?.scrollToEnd({ animated: false });
   143→    setTimeout(() => {
   144→      flatListRef.current?.scrollToEnd({ animated: false });
   145→    }, 100);
   146→  };
   147→
   148→  useEffect(() => {
   149→    const lastEvent = sortedEvents[sortedEvents.length - 1];
   150→    if (isAtBottomRef.current || lastEvent?.isOwn) return;
   151→
   152→    setShowScrollDown(true);
   153→  }, [isAtBottomRef.current, sortedEvents]);
   154→
   155→  return (
   156→    <>
   157→      <KeyboardAvoidingView style={styles.flex} behavior="padding">
   158→        {loadingMessage && <Loading />}
   159→        <FlashList
   160→          ref={flatListRef}
   161→          data={eventsWithDividers}
   162→          keyExtractor={(item) => {
   163→            if (item.type === "divider") return item.id;
   164→
   165→            return getItemUniqueKey(item.data) ?? "";
   166→          }}
   167→          maintainVisibleContentPosition={{
   168→            startRenderingFromBottom: true,
   169→          }}
   170→          extraData={updateTrigger}
   171→          contentContainerStyle={styles.listContent}
   172→          refreshing={refreshing}
   173→          onContentSizeChange={handleContentSizeChange}
   174→          onRefresh={handleLoadMore}
   175→          onScroll={handleOnScroll}
   176→          renderItem={({ item }) => {
   177→            if (item.type === "divider") {
   178→              return <DateDivider date={item.date} />;
   179→            }
   180→
   181→            return (
   182→              <SingleMessageType
   183→                event={item.data}
   184→                isPreviousSameSender={handleIsPreviousSameSender(
   185→                  isDirect,
   186→                  sortedEvents,
   187→                  item.data,
   188→                )}
   189→                onMemberPress={openMemberDetails}
   190→              />
   191→            );
   192→          }}
   193→        />
   194→
   195→        <RoomInput roomId={roomId} />
   196→      </KeyboardAvoidingView>
   197→
   198→      <MessageContentBottomSheet roomId={roomId} />
   199→
   200→      <MemberDetailsBottomSheet
   201→        isBottomSheetOpen={isBottomSheetOpen}
   202→        selectedMember={selectedMember}
   203→        roomId={roomId}
   204→        onClose={closeMemberDetails}
   205→      />
   206→
   207→      {showScrollDown && (
   208→        <Block
   209→          absolute
   210→          offsets={{ right: 0, bottom: 100 }}
   211→          align="center"
   212→          justify="center"
   213→          width="100%"
   214→        >
   215→          <Button.Outline size="medium" onPress={handleScrollDown}>
   216→            <Text>New messages</Text>
   217→            <Image source={require("assets/icons/arrow-down.png")} />
   218→          </Button.Outline>
   219→        </Block>
   220→      )}
   221→
   222→      <ImageViewerModal />
   223→      <VideoViewerModal />
   224→    </>
   225→  );
   226→};
   227→
   228→const styles = StyleSheet.create({
   229→  flex: {
   230→    flex: 1,
   231→  },
   232→  listContent: {
   233→    paddingHorizontal: 20,
   234→    paddingTop: 12,
   235→    paddingBottom: 20,
   236→  },
   237→});
   238→

