     1→import type {
     2→  EventTimelineItem,
     3→  RoomInterface,
     4→  TaskHandleInterface,
     5→  TimelineInterface,
     6→} from "@unomed/react-native-matrix-sdk";
     7→import {
     8→  DateDividerMode,
     9→  MessageType_Tags,
    10→  MsgLikeKind_Tags,
    11→  ReceiptType,
    12→  TimelineDiff_Tags,
    13→  TimelineFilter,
    14→  TimelineFocus,
    15→  TimelineItemContent_Tags,
    16→  TimelineReadReceiptTracking,
    17→} from "@unomed/react-native-matrix-sdk";
    18→import { useSetAtom } from "jotai";
    19→import { MatrixAtoms } from "modules/matrix-client/jotai";
    20→import {
    21→  getEventId,
    22→  getItemUniqueKey,
    23→  getTransactionId,
    24→} from "modules/matrix-client/utils";
    25→import { NavigationContainerRef } from "modules/navigation/const";
    26→import { TimelineAtoms } from "modules/timeline";
    27→import { TimelineService } from "modules/timeline/service/TimelineService";
    28→import { useCallback, useEffect, useRef, useState } from "react";
    29→import Toast from "react-native-toast-message";
    30→
    31→/** Maximum age for a verification request to be considered valid (5 minutes) */
    32→const VERIFICATION_REQUEST_MAX_AGE_MS = 5 * 60 * 1000;
    33→
    34→/** Check if an event is a verification request */
    35→const isVerificationRequest = (event: EventTimelineItem): boolean => {
    36→  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return false;
    37→  const kind = event.content.inner.content.kind;
    38→  if (kind?.tag !== MsgLikeKind_Tags.Message) return false;
    39→  const msgType = kind.inner.content.msgType;
    40→  return (
    41→    msgType?.tag === MessageType_Tags.Other &&
    42→    msgType.inner.msgtype === "m.key.verification.request"
    43→  );
    44→};
    45→
    46→/** Check if a verification request is recent enough to be handled */
    47→const isRecentVerificationRequest = (event: EventTimelineItem): boolean => {
    48→  const eventTimestamp = Number(event.timestamp);
    49→  const now = Date.now();
    50→  const age = now - eventTimestamp;
    51→  return age < VERIFICATION_REQUEST_MAX_AGE_MS;
    52→};
    53→
    54→interface Props {
    55→  room: RoomInterface | undefined;
    56→  roomId: string;
    57→}
    58→
    59→export const useRoomTimeline = ({ room, roomId }: Props) => {
    60→  const [events, setEvents] = useState<EventTimelineItem[]>([]);
    61→  const [loadingMessage, setLoadingMessage] = useState(true);
    62→  /** Track processed verification request IDs to avoid duplicates */
    63→  const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
    64→  const [refreshing, setRefreshing] = useState(false);
    65→  const [updateTrigger, setUpdateTrigger] = useState(0);
    66→  const eventIdsRef = useRef<Set<string>>(new Set());
    67→  const timelineRef = useRef<TimelineInterface | null>(null);
    68→  const isPaginatingRef = useRef(false);
    69→  const timelinePaginateNumber = useRef<number>(20);
    70→  const setVerificationStatus = useSetAtom(MatrixAtoms.verificationStatus);
    71→  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
    72→  const [isDirect, setIsDirect] = useState(false);
    73→  /** FIFO queue of transactionIds for in-flight own messages, used to match the final echo Set diff */
    74→  const pendingTransactionIdsQueue = useRef<string[]>([]);
    75→
    76→  const upsertEvents = (
    77→    incoming: EventTimelineItem[],
    78→    position: "front" | "back" = "back",
    79→  ) => {
    80→    setEvents((prev) => {
    81→      const next = [...prev];
    82→      for (const e of incoming) {
    83→        const key = getItemUniqueKey(e);
    84→        if (!key) continue;
    85→
    86→        const existingIndex = next.findIndex(
    87→          (item) => getItemUniqueKey(item) === key,
    88→        );
    89→        if (existingIndex !== -1) {
    90→          next[existingIndex] = e;
    91→          continue;
    92→        }
    93→
    94→        // Own confirmed message arrived via Append/Insert before the Set diff —
    95→        // replace the matching pending local echo instead of adding a duplicate.
    96→        if (
    97→          e.isOwn &&
    98→          !e.localSendState &&
    99→          pendingTransactionIdsQueue.current.length > 0
   100→        ) {
   101→          const txId = pendingTransactionIdsQueue.current.shift();
   102→          if (txId) {
   103→            const txIndex = next.findIndex(
   104→              (item) => getItemUniqueKey(item) === txId,
   105→            );
   106→            if (txIndex !== -1) {
   107→              eventIdsRef.current.delete(txId);
   108→              eventIdsRef.current.add(key);
   109→              next[txIndex] = e;
   110→              continue;
   111→            }
   112→          }
   113→        }
   114→
   115→        eventIdsRef.current.add(key);
   116→        if (position === "front") next.unshift(e);
   117→        else next.push(e);
   118→      }
   119→      return next;
   120→    });
   121→  };
   122→
   123→  const handleVerificationRequest = (info: {
   124→    senderId: string;
   125→    flowId: string;
   126→  }) => {
   127→    setVerificationStatus("incomingRequest");
   128→    NavigationContainerRef.navigate("verifyUser", {
   129→      userId: info.senderId,
   130→      flowId: info.flowId,
   131→    });
   132→  };
   133→
   134→  const checkForVerificationRequests = useCallback(
   135→    (incoming: EventTimelineItem[]) => {
   136→      for (const event of incoming) {
   137→        if (event.isOwn) continue;
   138→
   139→        if (
   140→          !isVerificationRequest(event) ||
   141→          !isRecentVerificationRequest(event)
   142→        ) {
   143→          continue;
   144→        }
   145→
   146→        const flowId = getEventId(event);
   147→        if (!flowId) continue;
   148→
   149→        if (processedVerificationRequestsRef.current.has(flowId)) continue;
   150→
   151→        processedVerificationRequestsRef.current.add(flowId);
   152→
   153→        handleVerificationRequest({
   154→          senderId: event.sender,
   155→          flowId,
   156→        });
   157→
   158→        // Only handle one at a time
   159→        break;
   160→      }
   161→    },
   162→    [],
   163→  );
   164→
   165→  const markAsRead = async () => {
   166→    if (!room) return;
   167→
   168→    try {
   169→      await room.markAsRead(ReceiptType.Read);
   170→    } catch (error) {
   171→      console.error("Failed to mark room as read:", error);
   172→    }
   173→  };
   174→
   175→  const loadMoreMessages = async () => {
   176→    if (!room || !timelineRef.current) return;
   177→
   178→    isPaginatingRef.current = true;
   179→    setRefreshing(true);
   180→
   181→    try {
   182→      await timelineRef.current.paginateBackwards(
   183→        timelinePaginateNumber.current,
   184→      );
   185→      timelinePaginateNumber.current += 20;
   186→    } catch (error) {
   187→      console.error("Failed to load more messages:", error);
   188→    } finally {
   189→      setRefreshing(false);
   190→      isPaginatingRef.current = false;
   191→    }
   192→  };
   193→
   194→  useEffect(() => {
   195→    if (!room) return;
   196→    setPinnedEventIds([]);
   197→    TimelineService.getPinnedEventIds(roomId)
   198→      .then(setPinnedEventIds)
   199→      .catch(console.error);
   200→  }, [roomId]);
   201→
   202→  useEffect(() => {
   203→    if (!room) return;
   204→
   205→    // Reset state when room changes
   206→    setEvents([]);
   207→    eventIdsRef.current.clear();
   208→
   209→    let timelineListenerHandle: TaskHandleInterface | null = null;
   210→
   211→    const initRoomTimeline = async () => {
   212→      try {
   213→        const timeline = await room.timelineWithConfiguration({
   214→          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
   215→          filter: new TimelineFilter.All(),
   216→          internalIdPrefix: undefined,
   217→          dateDividerMode: DateDividerMode.Daily,
   218→          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
   219→          reportUtds: false,
   220→        });
   221→
   222→        // Store timeline in ref for reuse in pagination
   223→        timelineRef.current = timeline;
   224→
   225→        // Set up listener BEFORE paginateBackwards so the SDK's initial
   226→        // cached diffs (from SQLite) are received immediately — no network needed.
   227→        let receivedInitialItems = false;
   228→
   229→        // Set up timeline listener for real-time updates
   230→        timelineListenerHandle = await timeline.addListener({
   231→          onUpdate: (diffs) => {
   232→            markAsRead();
   233→            // Trigger re-render to update read receipts and other event properties
   234→            setUpdateTrigger((prev) => prev + 1);
   235→
   236→            diffs.forEach((diff) => {
   237→              const change = diff.tag;
   238→              switch (change) {
   239→                case TimelineDiff_Tags.Append: {
   240→                  const newItems = diff.inner.values;
   241→                  if (newItems.length) {
   242→                    const eventItems = newItems
   243→                      .map((i) => i.asEvent())
   244→                      .filter((i): i is EventTimelineItem => !!i);
   245→
   246→                    if (eventItems.length > 0) {
   247→                      upsertEvents(eventItems, "back");
   248→                      checkForVerificationRequests(eventItems);
   249→                    }
   250→                  }
   251→                  break;
   252→                }
   253→                case TimelineDiff_Tags.Insert: {
   254→                  const { value } = diff.inner;
   255→                  const ev = value.asEvent();
   256→                  if (ev) {
   257→                    upsertEvents([ev], "back");
   258→                    checkForVerificationRequests([ev]);
   259→                  }
   260→                  break;
   261→                }
   262→                case TimelineDiff_Tags.Set: {
   263→                  const { value } = diff.inner;
   264→                  const ev = value.asEvent();
   265→                  if (ev) {
   266→                    const key = getItemUniqueKey(ev);
   267→                    if (!key) break;
   268→
   269→                    setEvents((prev) => {
   270→                      const next = [...prev];
   271→                      const existingIndex = next.findIndex(
   272→                        (e) => getItemUniqueKey(e) === key,
   273→                      );
   274→                      if (existingIndex !== -1) {
   275→                        next[existingIndex] = ev;
   276→                        return next;
   277→                      }
   278→
   279→                      // transactionId → eventId transition: pop from FIFO queue
   280→                      const txId =
   281→                        pendingTransactionIdsQueue.current.shift();
   282→                      if (txId) {
   283→                        const txIndex = next.findIndex(
   284→                          (e) => getItemUniqueKey(e) === txId,
   285→                        );
   286→                        if (txIndex !== -1) {
   287→                          eventIdsRef.current.delete(txId);
   288→                          eventIdsRef.current.add(key);
   289→                          next[txIndex] = ev;
   290→                          return next;
   291→                        }
   292→                      }
   293→
   294→                      // Not found — add as new (e.g. paginated echo)
   295→                      if (!eventIdsRef.current.has(key)) {
   296→                        eventIdsRef.current.add(key);
   297→                        return [...prev, ev];
   298→                      }
   299→                      return prev;
   300→                    });
   301→                  }
   302→                  break;
   303→                }
   304→                case TimelineDiff_Tags.Remove: {
   305→                  const { index: removeIndex } = diff.inner;
   306→                  setEvents((prev) => {
   307→                    const next = prev.filter((_, idx) => idx !== removeIndex);
   308→                    eventIdsRef.current = new Set(
   309→                      next
   310→                        .map(getItemUniqueKey)
   311→                        .filter(Boolean) as string[],
   312→                    );
   313→                    return next;
   314→                  });
   315→                  break;
   316→                }
   317→                case TimelineDiff_Tags.PushFront: {
   318→                  const { value } = diff.inner;
   319→                  const ev = value.asEvent();
   320→                  if (ev) {
   321→                    upsertEvents([ev], "front");
   322→                    checkForVerificationRequests([ev]);
   323→                  }
   324→                  break;
   325→                }
   326→                case TimelineDiff_Tags.PushBack: {
   327→                  const { value } = diff.inner;
   328→                  const ev = value.asEvent();
   329→                  if (ev) {
   330→                    const txId = getTransactionId(ev);
   331→                    if (txId) {
   332→                      pendingTransactionIdsQueue.current.push(txId);
   333→                    }
   334→                    upsertEvents([ev], "back");
   335→                    checkForVerificationRequests([ev]);
   336→                  }
   337→                  break;
   338→                }
   339→                case TimelineDiff_Tags.Reset: {
   340→                  const resetItems = diff.inner.values;
   341→                  pendingTransactionIdsQueue.current = [];
   342→                  if (resetItems.length) {
   343→                    const eventItems = resetItems
   344→                      .map((i) => i.asEvent())
   345→                      .filter((i): i is EventTimelineItem => !!i);
   346→
   347→                    // Deduplicate events in case Reset contains duplicates
   348→                    const seenIds = new Set<string>();
   349→                    const uniqueEvents: EventTimelineItem[] = [];
   350→
   351→                    for (const event of eventItems) {
   352→                      const key = getItemUniqueKey(event);
   353→                      if (key && !seenIds.has(key)) {
   354→                        seenIds.add(key);
   355→                        uniqueEvents.push(event);
   356→                      }
   357→                    }
   358→
   359→                    eventIdsRef.current = seenIds;
   360→                    setEvents(uniqueEvents);
   361→                  }
   362→                  break;
   363→                }
   364→                case TimelineDiff_Tags.Truncate: {
   365→                  const { length: cut } = diff.inner;
   366→                  setEvents((prev) => {
   367→                    const next = prev.slice(0, cut);
   368→                    eventIdsRef.current = new Set(
   369→                      next
   370→                        .map(getItemUniqueKey)
   371→                        .filter(Boolean) as string[],
   372→                    );
   373→                    return next;
   374→                  });
   375→                  break;
   376→                }
   377→                case TimelineDiff_Tags.Clear: {
   378→                  eventIdsRef.current = new Set();
   379→                  setEvents([]);
   380→                  break;
   381→                }
   382→                default:
   383→                  console.log("Unknown timeline change type:", change);
   384→              }
   385→            });
   386→
   387→            // Hide loading spinner on first update (cached items from SQLite
   388→            // or live items from network — whichever arrives first)
   389→            if (!receivedInitialItems) {
   390→              receivedInitialItems = true;
   391→              setLoadingMessage(false);
   392→            }
   393→          },
   394→        });
   395→
   396→        // Paginate after the listener is set up so events flow through it.
   397→        // Don't await — cached messages are already visible; network results
   398→        // will arrive as further diffs without blocking the UI.
   399→        timeline
   400→          .paginateBackwards(timelinePaginateNumber.current)
   401→          .then(() => {
   402→            timelinePaginateNumber.current += 20;
   403→            // Fallback: hide loader for empty rooms where listener never fired
   404→            setLoadingMessage(false);
   405→          })
   406→          .catch((error) => {
   407→            // Offline or network error — user already sees cached messages
   408→            console.warn("Failed to load initial messages:", error);
   409→            setLoadingMessage(false);
   410→          });
   411→      } catch (error) {
   412→        console.error("Failed to initialize room timeline:", error);
   413→        Toast.show({
   414→          text1: "Failed to load the messages. Please try again.",
   415→          type: "error",
   416→        });
   417→        NavigationContainerRef.goBack();
   418→        return null;
   419→      }
   420→    };
   421→
   422→    initRoomTimeline();
   423→
   424→    return () => {
   425→      timelineListenerHandle?.cancel?.();
   426→      timelineRef.current = null;
   427→    };
   428→  }, [roomId, checkForVerificationRequests]);
   429→
   430→  useEffect(() => {
   431→    markAsRead().catch(console.error);
   432→    room?.isDirect().then(setIsDirect).catch(console.error);
   433→  }, []);
   434→
   435→  return {
   436→    events,
   437→    loadingMessage,
   438→    refreshing,
   439→    timelineRef,
   440→    isPaginatingRef,
   441→    updateTrigger,
   442→    isDirect,
   443→    loadMoreMessages,
   444→    markAsRead,
   445→  };
   446→};
