     1→import type {
     2→  EventTimelineItem,
     3→  RoomInterface,
     4→  TaskHandleInterface,
     5→  TimelineInterface,
     6→} from "@unomed/react-native-matrix-sdk";
     7→import {
     8→  DateDividerMode,
     9→  RoomMessageEventMessageType,
    10→  TimelineDiff_Tags,
    11→  TimelineFilter,
    12→  TimelineFocus,
    13→  TimelineReadReceiptTracking,
    14→} from "@unomed/react-native-matrix-sdk";
    15→import { getEventId } from "modules/matrix-client/utils";
    16→import { useCallback, useEffect, useRef, useState } from "react";
    17→
    18→//TODO: Make a timeline module
    19→
    20→interface UseMediaTimelineProps {
    21→  room: RoomInterface | undefined;
    22→  roomId: string;
    23→}
    24→
    25→export const useMediaTimeline = ({ room, roomId }: UseMediaTimelineProps) => {
    26→  const [mediaItems, setMediaItems] = useState<EventTimelineItem[]>([]);
    27→  const [loading, setLoading] = useState(true);
    28→  const eventIdsRef = useRef<Set<string>>(new Set());
    29→  const timelineRef = useRef<TimelineInterface | null>(null);
    30→
    31→  const upsertMediaItems = useCallback((incoming: EventTimelineItem[]) => {
    32→    setMediaItems((prev) => {
    33→      const next = [...prev];
    34→      for (const event of incoming) {
    35→        const id = getEventId(event);
    36→        if (!id || eventIdsRef.current.has(id)) continue;
    37→
    38→        eventIdsRef.current.add(id);
    39→        next.push(event);
    40→      }
    41→      return next.sort((a, b) => Number(b.timestamp) - Number(a.timestamp));
    42→    });
    43→  }, []);
    44→
    45→  useEffect(() => {
    46→    if (!room) return;
    47→
    48→    setLoading(true);
    49→    setMediaItems([]);
    50→    eventIdsRef.current.clear();
    51→
    52→    let timelineListenerHandle: TaskHandleInterface | null = null;
    53→
    54→    const initMediaTimeline = async () => {
    55→      try {
    56→        const timeline = await room.timelineWithConfiguration({
    57→          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
    58→          filter: new TimelineFilter.OnlyMessage({
    59→            types: [
    60→              RoomMessageEventMessageType.Image,
    61→              RoomMessageEventMessageType.Video,
    62→            ],
    63→          }),
    64→          internalIdPrefix: "media_",
    65→          dateDividerMode: DateDividerMode.Daily,
    66→          trackReadReceipts: TimelineReadReceiptTracking.Disabled,
    67→          reportUtds: false,
    68→        });
    69→
    70→        timelineRef.current = timeline;
    71→
    72→        // Set up timeline listener for updates
    73→        timelineListenerHandle = await timeline.addListener({
    74→          onUpdate: (diffs) => {
    75→            diffs.forEach((diff) => {
    76→              const change = diff.tag;
    77→              switch (change) {
    78→                case TimelineDiff_Tags.Append: {
    79→                  const newItems = diff.inner.values;
    80→                  if (newItems.length) {
    81→                    const eventItems = newItems
    82→                      .map((i) => i.asEvent())
    83→                      .filter((i): i is EventTimelineItem => !!i);
    84→                    if (eventItems.length > 0) upsertMediaItems(eventItems);
    85→                  }
    86→                  break;
    87→                }
    88→                case TimelineDiff_Tags.Insert:
    89→                case TimelineDiff_Tags.PushFront:
    90→                case TimelineDiff_Tags.PushBack: {
    91→                  const { value } = diff.inner;
    92→                  const ev = value.asEvent();
    93→                  if (ev) upsertMediaItems([ev]);
    94→                  break;
    95→                }
    96→                case TimelineDiff_Tags.Set: {
    97→                  const { value } = diff.inner;
    98→                  const ev = value.asEvent();
    99→                  if (ev) {
   100→                    const id = getEventId(ev);
   101→                    if (!id) break;
   102→
   103→                    setMediaItems((prev) => {
   104→                      const existingIndex = prev.findIndex(
   105→                        (item) => getEventId(item) === id,
   106→                      );
   107→                      if (existingIndex >= 0) {
   108→                        const next = [...prev];
   109→                        next[existingIndex] = ev;
   110→                        return next;
   111→                      }
   112→                      return prev;
   113→                    });
   114→                  }
   115→                  break;
   116→                }
   117→                case TimelineDiff_Tags.Remove: {
   118→                  const { index: removeIndex } = diff.inner;
   119→                  setMediaItems((prev) => {
   120→                    const next = prev.filter((_, idx) => idx !== removeIndex);
   121→                    eventIdsRef.current = new Set(
   122→                      next
   123→                        .map((item) => getEventId(item))
   124→                        .filter(Boolean) as string[],
   125→                    );
   126→                    return next;
   127→                  });
   128→                  break;
   129→                }
   130→                case TimelineDiff_Tags.Reset: {
   131→                  const resetItems = diff.inner.values;
   132→                  if (resetItems.length) {
   133→                    const eventItems = resetItems
   134→                      .map((i) => i.asEvent())
   135→                      .filter((i): i is EventTimelineItem => !!i);
   136→
   137→                    const seenIds = new Set<string>();
   138→                    const newMediaItems: EventTimelineItem[] = [];
   139→
   140→                    for (const event of eventItems) {
   141→                      const id = getEventId(event);
   142→                      if (id && !seenIds.has(id)) {
   143→                        seenIds.add(id);
   144→                        newMediaItems.push(event);
   145→                      }
   146→                    }
   147→
   148→                    eventIdsRef.current = seenIds;
   149→                    setMediaItems(
   150→                      newMediaItems.sort(
   151→                        (a, b) => Number(b.timestamp) - Number(a.timestamp),
   152→                      ),
   153→                    );
   154→                  }
   155→                  break;
   156→                }
   157→                case TimelineDiff_Tags.Clear: {
   158→                  eventIdsRef.current.clear();
   159→                  setMediaItems([]);
   160→                  break;
   161→                }
   162→                default:
   163→                  break;
   164→              }
   165→            });
   166→          },
   167→        });
   168→
   169→        // Paginate backwards until we reach the start of the timeline
   170→        let reachedStart = false;
   171→        while (!reachedStart) {
   172→          reachedStart = await timeline.paginateBackwards(100);
   173→        }
   174→
   175→        setLoading(false);
   176→      } catch (error) {
   177→        console.error("Failed to initialize media timeline:", error);
   178→        setLoading(false);
   179→      }
   180→    };
   181→
   182→    initMediaTimeline();
   183→
   184→    return () => {
   185→      timelineListenerHandle?.cancel?.();
   186→      timelineRef.current = null;
   187→    };
   188→  }, [roomId, room, upsertMediaItems]);
   189→
   190→  return {
   191→    mediaItems,
   192→    loading,
   193→  };
   194→};
